public class InnerChannelIcebergDestinationConfigurationFactory(Action<Humidifier.MSK.ChannelTypes.IcebergDestinationConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MSK.ChannelTypes.IcebergDestinationConfiguration>
{

    internal InnerChannelDeadLetterQueueS3Factory DeadLetterQueueS3Factory { get; set; }

    internal InnerChannelSchemaEvolutionFactory SchemaEvolutionFactory { get; set; }

    internal InnerChannelTableCreationFactory TableCreationFactory { get; set; }

    internal InnerChannelCatalogFactory CatalogFactory { get; set; }

    protected override Humidifier.MSK.ChannelTypes.IcebergDestinationConfiguration Create()
    {
        var icebergDestinationConfigurationResult = CreateIcebergDestinationConfiguration();
        factoryAction?.Invoke(icebergDestinationConfigurationResult);

        return icebergDestinationConfigurationResult;
    }

    private Humidifier.MSK.ChannelTypes.IcebergDestinationConfiguration CreateIcebergDestinationConfiguration()
    {
        var icebergDestinationConfigurationResult = new Humidifier.MSK.ChannelTypes.IcebergDestinationConfiguration();

        return icebergDestinationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MSK.ChannelTypes.IcebergDestinationConfiguration result)
    {
        base.CreateChildren(result);

        result.DeadLetterQueueS3 ??= DeadLetterQueueS3Factory?.Build();
        result.SchemaEvolution ??= SchemaEvolutionFactory?.Build();
        result.TableCreation ??= TableCreationFactory?.Build();
        result.Catalog ??= CatalogFactory?.Build();
    }

} // End Of Class

